{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.store_replen_1 as WITH size_extraction AS ( SELECT branch_code, branch_name, REVERSE(SUBSTRING(REVERSE(logicusercode), 1, POSITION(\'-\', REVERSE(logicusercode)) - 1)) AS size, CASE WHEN POSITION(\'-\' IN LOGICUSERCODE) > 0 AND LEFT(LOGICUSERCODE, 2) = \'SH\' THEN SPLIT_PART(LOGICUSERCODE, \'-\', 1) WHEN POSITION(\'-\' IN LOGICUSERCODE) > 0 THEN SPLIT_PART(LOGICUSERCODE, \'-\', 1) || \'-\' || SPLIT_PART(LOGICUSERCODE, \'-\', 2) ELSE LOGICUSERCODE END AS sku_group, logicusercode, sum(stock_qty) as stock_qty, CASE WHEN size=\'28\' THEN \'XS\' WHEN size=\'30\' THEN \'S\' WHEN size=\'32\' THEN \'M\' WHEN size=\'34\' THEN \'L\' WHEN size=\'36\' THEN \'XL\' WHEN size=\'38\' THEN \'XXL\' WHEN size=\'40\' THEN \'3XL\' WHEN size=\'42\' THEN \'4XL\' WHEN size=\'44\' THEN \'5XL\' WHEN size=\'46\' THEN \'6XL\' WHEN size=\'48\' THEN \'7XL\' WHEN size=\'50\' THEN \'8XL\' WHEN size=\'\' THEN \'NA\' WHEN size IS NULL THEN \'NA\' ELSE size END AS size_mapped FROM snitch_db.maplemonk.logicerp23_24_get_stock_in_hand WHERE date = CURRENT_DATE AND logicusercode NOT LIKE \'%CB%\' group by branch_code,branch_name,size,sku_group,logicusercode,size_mapped ), size_extraction_pivot_up AS ( SELECT branch_code, branch_name, sku_group, coalesce(SUM(CASE WHEN size_mapped = \'XS\' THEN stock_qty ELSE 0 END),0) AS XS_units_store, coalesce(SUM(CASE WHEN size_mapped = \'S\' THEN stock_qty ELSE 0 END),0) AS S_units_store, coalesce(SUM(CASE WHEN size_mapped = \'M\' THEN stock_qty ELSE 0 END),0) AS M_units_store, coalesce(SUM(CASE WHEN size_mapped = \'L\' THEN stock_qty ELSE 0 END),0) AS L_units_store, coalesce(SUM(CASE WHEN size_mapped = \'XL\' THEN stock_qty ELSE 0 END),0) AS XL_units_store, coalesce(SUM(CASE WHEN (size_mapped = \'XXL\' OR size_mapped = \'XXl\' or size_mapped = \'2XL\') THEN stock_qty ELSE 0 END),0) AS XXL_units_store, coalesce(SUM(CASE WHEN size_mapped = \'3XL\' THEN stock_qty ELSE 0 END),0) AS XL3_units_store, coalesce(SUM(CASE WHEN size_mapped = \'4XL\' THEN stock_qty ELSE 0 END),0) AS XL4_units_store, coalesce(SUM(CASE WHEN size_mapped = \'5XL\' THEN stock_qty ELSE 0 END),0) AS XL5_units_store, coalesce(SUM(CASE WHEN size_mapped = \'6XL\' THEN stock_qty ELSE 0 END),0) AS XL6_units_store, coalesce(SUM(CASE WHEN size_mapped = \'NA\' THEN stock_qty ELSE 0 END),0) AS NA_units_store FROM size_extraction GROUP BY sku_group, branch_code, branch_name ), size_count AS ( SELECT branch_code, sku_group, COUNT(DISTINCT size) AS num_size_available FROM size_extraction GROUP BY branch_code, sku_group ), store_priority AS ( SELECT BRANCH_CODE_PRIORITY, BRANCH_NAME_PRIORITY, SHORT_NAME, cast(priority as integer) as priority FROM snitch_db.maplemonk.storepriority ), ItemData AS ( SELECT branch_code, marketplace, sku, sku_group, category, REVERSE(SUBSTRING(REVERSE(sku), 1, POSITION(\'-\', REVERSE(sku)) - 1)) AS size, CASE WHEN size=\'28\' THEN \'XS\' WHEN size=\'30\' THEN \'S\' WHEN size=\'32\' THEN \'M\' WHEN size=\'34\' THEN \'L\' WHEN size=\'36\' THEN \'XL\' WHEN size=\'38\' THEN \'XXL\' WHEN size=\'40\' THEN \'3XL\' WHEN size=\'42\' THEN \'4XL\' WHEN size=\'44\' THEN \'5XL\' WHEN size=\'46\' THEN \'6XL\' WHEN size=\'48\' THEN \'7XL\' WHEN size=\'50\' THEN \'8XL\' WHEN size=\'\' THEN \'NA\' WHEN size IS NULL THEN \'NA\' ELSE size END AS size_mapped, SUM(suborder_quantity) AS units_sold FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE order_date >= current_date - 30 AND sku NOT LIKE \'CB%\' AND category IN (\'SHIRT\') GROUP BY branch_code, sku, sku_group, size, size_mapped, marketplace, category ), CategoryUnitsSold AS ( SELECT branch_code, category, size_mapped, SUM(units_sold) AS category_units_sold FROM ItemData GROUP BY branch_code, category, size_mapped ), SizeRatio AS ( SELECT branch_code, size_mapped, ROUND((SUM(category_units_sold) / SUM(SUM(category_units_sold)) OVER (PARTITION BY branch_code,category)) * 100, 2) AS size_ratio_percentage FROM CategoryUnitsSold GROUP BY branch_code, size_mapped, category ), FinalData AS ( SELECT se.branch_code, se.branch_name, se.size, se.size_mapped, se.sku_group, se.logicusercode, se_pvup.XS_units_store, se_pvup.S_units_store, se_pvup.M_units_store, se_pvup.L_units_store, se_pvup.XL_units_store, se_pvup.XXL_units_store, se_pvup.XL3_units_store, se_pvup.XL4_units_store, se_pvup.XL5_units_store, se_pvup.XL6_units_store, se_pvup.NA_units_store, SUM(se.stock_qty) AS units_on_hand, sc.num_size_available, COALESCE(sr.size_ratio_percentage, 100) AS size_ratio_percentage, SUM(COALESCE(sr.size_ratio_percentage, 100)) OVER (PARTITION BY se.branch_code,se.sku_group) AS sum_size_ratio_percentage_by_sku_group FROM size_extraction se JOIN size_count sc ON se.sku_group = sc.sku_group and se.branch_code=sc.branch_code LEFT JOIN SizeRatio sr ON se.size_mapped = sr.size_mapped and se.branch_code=sr.branch_code LEFT JOIN size_extraction_pivot_up se_pvup ON se.sku_group=se_pvup.sku_group and se.branch_code=se_pvup.branch_code GROUP BY se.branch_code, se.branch_name, se.size, se.size_mapped, se.sku_group, se.logicusercode, sc.num_size_available, sr.size_ratio_percentage, se_pvup.XS_units_store, se_pvup.S_units_store, se_pvup.M_units_store, se_pvup.L_units_store, se_pvup.XL_units_store, se_pvup.XXL_units_store, se_pvup.XL3_units_store, se_pvup.XL4_units_store, se_pvup.XL5_units_store, se_pvup.XL6_units_store, se_pvup.NA_units_store ) SELECT fd.*, am.id, am.price, am.product_name, upper(am.category) as availability_category, am.xs_units, am.s_units, am.m_units, am.l_units, am.xl_units, am.xxl_units, am.xl3_units, am.xl4_units, am.xl5_units, am.xl6_units, am.sellable_inventory, am.sku_class, am.num_size_available as num_size_wh, sp.priority FROM FinalData fd LEFT JOIN snitch_db.maplemonk.availability_master_v2 am ON fd.sku_group = am.sku_group LEFT JOIN store_priority sp ON fd.branch_code=sp.BRANCH_CODE_PRIORITY ORDER BY sp.priority, fd.units_on_hand DESC; create or replace table snitch_db.maplemonk.store_replen_1_feb2025 as WITH sizeCombsFromInv AS ( SELECT branch_code, REVERSE(SUBSTRING(REVERSE(ADDLITEMCODE), 1, POSITION(\'-\', REVERSE(ADDLITEMCODE)) - 1)) AS size, CASE WHEN upper(ADDLITEMCODE) LIKE \'4C%\' THEN SPLIT_PART(ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(ADDLITEMCODE, \'-\', 2) || \'-\' || SPLIT_PART(ADDLITEMCODE, \'-\', 3) WHEN POSITION(\'-\' IN ADDLITEMCODE) > 0 THEN SPLIT_PART(ADDLITEMCODE, \'-\', 1) || \'-\' || SPLIT_PART(ADDLITEMCODE, \'-\', 2) ELSE ADDLITEMCODE END AS sku_group, ADDLITEMCODE, SUM(stock_qty) AS stock_qty, CASE WHEN ADDLITEMCODE LIKE \'SN%\' OR ADDLITEMCODE LIKE \'4MSFR%\' OR ADDLITEMCODE LIKE \'BP%\' THEN \'NA\' WHEN ADDLITEMCODE LIKE \'SH%\' THEN CASE WHEN size = \'39\' THEN \'XS\' WHEN size = \'40\' THEN \'S\' WHEN size = \'41\' THEN \'M\' WHEN size = \'42\' THEN \'L\' WHEN size = \'43\' THEN \'XL\' WHEN size = \'44\' THEN \'XXL\' WHEN size = \'45\' THEN \'3XL\' ELSE size END ELSE CASE WHEN size = \'28\' THEN \'XS\' WHEN size = \'30\' THEN \'S\' WHEN size = \'32\' THEN \'M\' WHEN size = \'34\' THEN \'L\' WHEN size = \'36\' THEN \'XL\' WHEN size = \'38\' THEN \'XXL\' WHEN size = \'40\' THEN \'3XL\' WHEN size = \'42\' THEN \'4XL\' WHEN size = \'44\' THEN \'5XL\' WHEN size = \'46\' THEN \'6XL\' WHEN size = \'48\' THEN \'7XL\' WHEN size = \'50\' THEN \'8XL\' WHEN size = \'\' THEN \'NA\' WHEN size IS NULL THEN \'NA\' ELSE size END END AS size_mapped FROM snitch_db.maplemonk.logicerp23_24_get_stock_in_hand WHERE date = CURRENT_DATE AND ADDLITEMCODE NOT LIKE \'%CB%\' GROUP BY branch_code, size, sku_group, ADDLITEMCODE, size_mapped ), sizeCombsFromSales AS ( SELECT branch_code, sku, sku_group, REVERSE(SUBSTRING(REVERSE(sku), 1, POSITION(\'-\', REVERSE(sku)) - 1)) AS size, CASE WHEN sku LIKE \'SN%\' OR sku LIKE \'4MSFR%\' OR sku LIKE \'BP%\' THEN \'NA\' WHEN sku LIKE \'SH%\' THEN CASE WHEN size = \'39\' THEN \'XS\' WHEN size = \'40\' THEN \'S\' WHEN size = \'41\' THEN \'M\' WHEN size = \'42\' THEN \'L\' WHEN size = \'43\' THEN \'XL\' WHEN size = \'44\' THEN \'XXL\' WHEN size = \'45\' THEN \'3XL\' ELSE size END ELSE CASE WHEN size = \'28\' THEN \'XS\' WHEN size = \'30\' THEN \'S\' WHEN size = \'32\' THEN \'M\' WHEN size = \'34\' THEN \'L\' WHEN size = \'36\' THEN \'XL\' WHEN size = \'38\' THEN \'XXL\' WHEN size = \'40\' THEN \'3XL\' WHEN size = \'42\' THEN \'4XL\' WHEN size = \'44\' THEN \'5XL\' WHEN size = \'46\' THEN \'6XL\' WHEN size = \'48\' THEN \'7XL\' WHEN size = \'50\' THEN \'8XL\' WHEN size = \'\' THEN \'NA\' WHEN size IS NULL THEN \'NA\' ELSE size END END AS size_mapped FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE order_date >= CURRENT_DATE AND sku NOT LIKE \'CB%\' AND marketplace NOT LIKE (\'%SNITCH - WH%\') AND sku NOT LIKE (\'%4MCB%\') GROUP BY branch_code, sku, sku_group, size, size_mapped ), relevant_sku_branches AS ( SELECT DISTINCT branch_code, sku_group FROM sizeCombsFromInv UNION SELECT DISTINCT branch_code, sku_group FROM sizeCombsFromSales ), relevant_sizes AS ( SELECT DISTINCT sku_group, size, size_mapped FROM sizeCombsFromInv UNION SELECT DISTINCT sku_group, size, size_mapped FROM sizeCombsFromSales ), valid_combinations AS ( SELECT rb.branch_code, rs.sku_group, rs.size, rs.size_mapped FROM relevant_sku_branches rb INNER JOIN relevant_sizes rs ON rb.sku_group = rs.sku_group ), sizeExtract AS ( SELECT vc.branch_code, vc.sku_group, vc.size, vc.size_mapped, COALESCE(q1.ADDLITEMCODE, CONCAT(vc.sku_group, \'-\', vc.size)) AS logicusercode, COALESCE(q1.stock_qty, 0) AS stock_qty FROM valid_combinations vc LEFT JOIN sizeCombsFromInv q1 ON vc.branch_code = q1.branch_code AND vc.sku_group = q1.sku_group AND vc.size = q1.size ), sizeExtractPivotUp AS ( SELECT branch_code, sku_group, COALESCE(SUM(CASE WHEN size_mapped = \'XS\' THEN stock_qty ELSE 0 END), 0) AS XS_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'S\' THEN stock_qty ELSE 0 END), 0) AS S_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'M\' THEN stock_qty ELSE 0 END), 0) AS M_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'L\' THEN stock_qty ELSE 0 END), 0) AS L_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'XL\' THEN stock_qty ELSE 0 END), 0) AS XL_units_store, COALESCE(SUM(CASE WHEN size_mapped IN (\'XXL\', \'XXl\', \'2XL\') THEN stock_qty ELSE 0 END), 0) AS XXL_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'3XL\' THEN stock_qty ELSE 0 END), 0) AS XL3_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'4XL\' THEN stock_qty ELSE 0 END), 0) AS XL4_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'5XL\' THEN stock_qty ELSE 0 END), 0) AS XL5_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'6XL\' THEN stock_qty ELSE 0 END), 0) AS XL6_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'7XL\' THEN stock_qty ELSE 0 END), 0) AS XL7_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'8XL\' THEN stock_qty ELSE 0 END), 0) AS XL8_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'NA\' THEN stock_qty ELSE 0 END), 0) AS NA_units_store FROM sizeExtract GROUP BY branch_code, sku_group ), sizeCount AS ( SELECT branch_code, sku_group, COUNT(DISTINCT CASE WHEN stock_qty > 0 THEN size END) AS num_size_available FROM sizeExtract GROUP BY branch_code, sku_group ), store_priority AS ( SELECT BRANCH_CODE_PRIORITY, BRANCH_NAME_PRIORITY, SHORT_NAME, cast(PRIORITY as integer) as PRIORITY FROM snitch_db.maplemonk.storepriority ), ItemData AS ( WITH sales_data AS ( SELECT branch_code, marketplace, sku, sku_group, --category, REVERSE(SPLIT_PART(REVERSE(sku), \'-\', 1)) AS size, CASE WHEN sku LIKE \'SN%\' OR sku LIKE \'4MSFR%\' OR sku LIKE \'BP%\' THEN \'NA\' WHEN sku LIKE \'SH%\' THEN CASE WHEN size = \'39\' THEN \'XS\' WHEN size = \'40\' THEN \'S\' WHEN size = \'41\' THEN \'M\' WHEN size = \'42\' THEN \'L\' WHEN size = \'43\' THEN \'XL\' WHEN size = \'44\' THEN \'XXL\' WHEN size = \'45\' THEN \'3XL\' ELSE size END ELSE CASE WHEN size = \'28\' THEN \'XS\' WHEN size = \'30\' THEN \'S\' WHEN size = \'32\' THEN \'M\' WHEN size = \'34\' THEN \'L\' WHEN size = \'36\' THEN \'XL\' WHEN size = \'38\' THEN \'XXL\' WHEN size = \'40\' THEN \'3XL\' WHEN size = \'42\' THEN \'4XL\' WHEN size = \'44\' THEN \'5XL\' WHEN size = \'46\' THEN \'6XL\' WHEN size = \'48\' THEN \'7XL\' WHEN size = \'50\' THEN \'8XL\' WHEN size = \'\' THEN \'NA\' WHEN size IS NULL THEN \'NA\' ELSE size END END AS size_mapped, order_date, SUM(suborder_quantity) AS units_sold FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE order_date >= CURRENT_DATE - INTERVAL \'45 DAYS\' AND sku NOT LIKE \'CB%\' AND marketplace not like (\'%SNITCH - WH%\') AND sku not like (\'%4MCB%\') GROUP BY branch_code, sku, sku_group, size, size_mapped, marketplace, order_date ), first_sale AS ( SELECT sku_group, branch_code, MIN(order_date) AS first_sale_date FROM sales_data GROUP BY sku_group, branch_code ), total_sales AS ( SELECT s.branch_code, s.marketplace, s.sku, s.sku_group, s.size, s.size_mapped, f.first_sale_date, SUM(s.units_sold) AS total_units_sold, DATEDIFF(DAY, f.first_sale_date, CURRENT_DATE) AS days_elapsed FROM sales_data s LEFT JOIN first_sale f ON s.sku_group = f.sku_group and s.branch_code = f.branch_code GROUP BY s.branch_code, s.marketplace, s.sku, s.sku_group, s.size, s.size_mapped, f.first_sale_date ), sales_last_7_days AS ( SELECT s.sku, s.branch_code, SUM(s.units_sold) AS units_sold_last_7_days FROM sales_data s LEFT JOIN first_sale f ON s.sku_group = f.sku_group and s.branch_code = f.branch_code WHERE s.order_date >= CASE WHEN DATEDIFF(DAY, f.first_sale_date, CURRENT_DATE) < 7 THEN f.first_sale_date ELSE CURRENT_DATE - INTERVAL \'7 DAYS\' END GROUP BY s.sku,s.branch_code ) SELECT ts.branch_code, ts.marketplace, ts.sku, ts.sku_group, ts.size, ts.size_mapped, ts.first_sale_date, ts.total_units_sold, ts.days_elapsed, CASE WHEN ts.days_elapsed = 0 THEN 0 ELSE ROUND(ts.total_units_sold / NULLIF(ts.days_elapsed, 0), 2) END AS natural_rate_of_sale, COALESCE(sl7.units_sold_last_7_days, 0) AS units_sold_last_7_days, CASE WHEN ts.days_elapsed < 7 THEN ts.days_elapsed ELSE 7 END AS days_for_7_day_sales, CASE WHEN ts.days_elapsed = 0 THEN 0 ELSE ROUND(COALESCE(sl7.units_sold_last_7_days, 0) / NULLIF( CASE WHEN ts.days_elapsed < 7 THEN ts.days_elapsed ELSE 7 END, 0), 2) END AS seven_day_rate_of_sale FROM total_sales ts LEFT JOIN sales_last_7_days sl7 ON ts.sku = sl7.sku and ts.branch_code = sl7.branch_code GROUP BY ts.branch_code, ts.marketplace, ts.sku, ts.sku_group, ts.size, ts.size_mapped, ts.first_sale_date, ts.total_units_sold, ts.days_elapsed, natural_rate_of_sale, units_sold_last_7_days, days_for_7_day_sales, seven_day_rate_of_sale ), CategoryUnitsSold AS ( SELECT branch_code, sku_group, size_mapped, SUM(total_units_sold) AS category_units_sold FROM ItemData GROUP BY branch_code, sku_group, size_mapped ), SizeRatio AS ( SELECT sku_group, branch_code, size_mapped, SUM(total_units_sold) AS total_units_per_size, SUM(SUM(total_units_sold)) OVER (PARTITION BY sku_group, branch_code) AS total_units_per_sku_group, ROUND((SUM(total_units_sold) / SUM(SUM(total_units_sold)) OVER (PARTITION BY sku_group, branch_code)) * 100, 2) AS size_ratio_percentage FROM ItemData GROUP BY sku_group, branch_code, size_mapped ), FinalData AS ( SELECT se.branch_code, se.size, se.size_mapped, se.sku_group, se.logicusercode, se_pvup.XS_units_store, se_pvup.S_units_store, se_pvup.M_units_store, se_pvup.L_units_store, se_pvup.XL_units_store, se_pvup.XXL_units_store, se_pvup.XL3_units_store, se_pvup.XL4_units_store, se_pvup.XL5_units_store, se_pvup.XL6_units_store, se_pvup.XL7_units_store, se_pvup.XL8_units_store, se_pvup.NA_units_store, SUM(se.stock_qty) AS units_on_hand, sc.num_size_available, COALESCE(sr.size_ratio_percentage, 0) AS size_ratio_percentage, SUM(COALESCE(sr.size_ratio_percentage, 0)) OVER (PARTITION BY se.branch_code,se.sku_group) AS sum_size_ratio_percentage_by_sku_group, sum(coalesce(ItemData.total_units_sold,0)) as final_units_sold, sum(coalesce(ItemData.natural_rate_of_sale,0)) as final_natural_rate_of_sale, sum(coalesce(ItemData.seven_day_rate_of_sale,0)) as final_seven_day_rate_of_sale, ItemData.first_sale_date, ItemData.days_elapsed FROM sizeExtract se JOIN sizeCount sc ON se.sku_group = sc.sku_group and se.branch_code=sc.branch_code LEFT JOIN SizeRatio sr ON se.size_mapped = sr.size_mapped and se.branch_code=sr.branch_code and se.sku_group=sr.sku_group LEFT JOIN sizeExtractPivotUp se_pvup ON se.sku_group=se_pvup.sku_group and se.branch_code=se_pvup.branch_code LEFT JOIN ItemData ON se.logicusercode=ItemData.sku and se.branch_code=ItemData.branch_code GROUP BY se.branch_code, se.size, se.size_mapped, se.sku_group, se.logicusercode, sc.num_size_available, sr.size_ratio_percentage, se_pvup.XS_units_store, se_pvup.S_units_store, se_pvup.M_units_store, se_pvup.L_units_store, se_pvup.XL_units_store, se_pvup.XXL_units_store, se_pvup.XL3_units_store, se_pvup.XL4_units_store, se_pvup.XL5_units_store, se_pvup.XL6_units_store, se_pvup.XL7_units_store, se_pvup.XL8_units_store, se_pvup.NA_units_store, ItemData.first_sale_date, ItemData.days_elapsed ), ReplenData AS ( SELECT fd.*, am.id, am.price, am.product_name, UPPER(am.category) AS availability_category, am.xs_units, am.s_units, am.m_units, am.l_units, am.xl_units, am.xxl_units, am.xl3_units, am.xl4_units, am.xl5_units, am.xl6_units, am.na_units, am.xl7_units, am.xl8_units, am.sellable_inventory, am.sku_class, am.num_size_available AS num_size_wh, CAST(sp.priority AS INTEGER) AS priority, CASE WHEN fd.FINAL_NATURAL_RATE_OF_SALE < fd.FINAL_SEVEN_DAY_RATE_OF_SALE THEN fd.FINAL_SEVEN_DAY_RATE_OF_SALE ELSE fd.FINAL_NATURAL_RATE_OF_SALE END AS final_ros, CASE WHEN fd.DAYS_ELAPSED >= 4 THEN ROUND( CASE WHEN ((CASE WHEN fd.FINAL_NATURAL_RATE_OF_SALE < fd.FINAL_SEVEN_DAY_RATE_OF_SALE THEN fd.FINAL_SEVEN_DAY_RATE_OF_SALE ELSE fd.FINAL_NATURAL_RATE_OF_SALE END)*10 - fd.UNITS_ON_HAND) < 0 THEN 0 ELSE ((CASE WHEN fd.FINAL_NATURAL_RATE_OF_SALE < fd.FINAL_SEVEN_DAY_RATE_OF_SALE THEN fd.FINAL_SEVEN_DAY_RATE_OF_SALE ELSE fd.FINAL_NATURAL_RATE_OF_SALE END)*10 - fd.UNITS_ON_HAND) END,0) ELSE 0 END AS replen_nocap, CASE WHEN SIZE_MAPPED = \'NA\' THEN replen_nocap WHEN replen_nocap >= 6 THEN 6 ELSE replen_nocap END AS replen_cap FROM FinalData fd LEFT JOIN snitch_db.maplemonk.availability_master_v2 am ON fd.sku_group = am.sku_group LEFT JOIN store_priority sp ON fd.branch_code = sp.BRANCH_CODE_PRIORITY ), ReplenRatio AS ( SELECT branch_code, sku_group, SUM(replen_nocap) AS total_replen_cap_per_group FROM ReplenData GROUP BY branch_code, sku_group ) SELECT rd.*, CASE WHEN round(rr.total_replen_cap_per_group * rd.SIZE_RATIO_PERCENTAGE / NULLIF(rd.sum_size_ratio_percentage_by_sku_group, 0),0) is null THEN 0 ELSE round(rr.total_replen_cap_per_group * rd.SIZE_RATIO_PERCENTAGE / NULLIF(rd.sum_size_ratio_percentage_by_sku_group, 0),0) END AS replen_sale_ratio, CASE WHEN rd.SIZE_MAPPED = \'NA\' THEN replen_sale_ratio WHEN replen_sale_ratio < 6 THEN replen_sale_ratio ELSE 6 END AS replen_sale_ratio_capped, CASE WHEN total_replen_cap_per_group >0 AND replen_cap = 0 AND units_on_hand=0 THEN 1 ELSE 0 END AS addl_replen_sizes, (replen_cap+addl_replen_sizes) as replen_1 FROM ReplenData rd LEFT JOIN ReplenRatio rr ON rd.branch_code = rr.branch_code AND rd.sku_group = rr.sku_group ORDER BY rd.priority, rd.units_on_hand DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
